const { chromium } = await import('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.goto('https://www.markdownguide.org/basic-syntax/', { waitUntil: 'domcontentloaded', timeout: 30000 });
const text = await page.locator('body').innerText();
console.log(JSON.stringify({chars: text.length, last50: text.slice(-50), title: await page.title(), url: page.url()}));
await browser.close();
